  let mut bytes=Vec::new();let n=(&mut input).take(LIMIT+1).read_until(b'\n',&mut bytes)?;
  if n==0{break}if bytes.len() as u64>LIMIT||bytes.last()!=Some(&b'\n'){return Err("request too large".into())}
