  let response=match result {Ok(value)=>json!({"ok":value}),Err(error)=>json!({"error":error})};
  let output=serde_json::to_vec(&response)?;if output.len() as u64>LIMIT{return Err("worker response too large".into())}io::stdout().write_all(&output)?;io::stdout().write_all(b"\n")?;io::stdout().flush()?;
